function makeFileMapReader(fileMap) {
    return function(readOpts) {
        var p = readOpts.path;
        if (fileMap && fileMap.hasOwnProperty(p)) {
            return fileMap[p];
        }
        try {
            return file_read(readOpts);
        } catch (e) {}
        return null;
