        './.dmtools/resolver.js':
            'module.exports = function(ticket, candidateBaseBranch) { return "develop/forced"; };'
    });
    var config = cl.loadProjectConfig({
        customParams: {
            targetRepository: { owner: 'acme-corp', repo: 'example-repo', baseBranch: 'master' }
        }
