function applyBranchResolverFn(config, params, pathKey, logLabel) {
   var resolverPath = config.git && config.git[pathKey];
   if (!resolverPath || !params || !params.ticket) return;
   var resolver = loadHookFn(resolverPath, pathKey);
   if (!resolver) return;
   var isSnapshot = pathKey === 'snapshotBranchResolverFnPath';
   var candidate = isSnapshot ? (config.git.snapshotBranch || config.git.baseBranch) : config.git.baseBranch;
   var target = isSnapshot ? 'snapshotBranch' : 'baseBranch';
   try {
       var resolved = resolver(params.ticket, candidate, config);
