    var candidates = [
        path.resolve(PACK_ROOT, rel),
        path.resolve(PACK_ROOT, stripped),
        path.resolve(process.cwd(), p),
        path.resolve(process.cwd(), 'agents', rel)
    ];
    for (var i = 0; i < candidates.length; i++) {
