        if (tr.repo) config.repository.repo = tr.repo;
        if (tr.baseBranch) config.git.baseBranch = tr.baseBranch;
        if (tr.workingDir) config.workingDir = tr.workingDir;
        console.log('configLoader: Applied targetRepository override → ' +
