 * @param {string} template - Template with {varName} placeholders
 * @param {Object} vars - Key-value pairs for substitution
 * @returns {string} Resolved string
 */
function formatTemplate(template, vars) {
    if (!template) return '';
    var result = template;
    for (var key in vars) {
        if (vars.hasOwnProperty(key)) {
