 */
function formatTemplate(template, vars) {
    if (!template) return '';
    var result = template;
    for (var key in vars) {
        if (vars.hasOwnProperty(key)) {
            // Replace all occurrences of {key}
            var placeholder = '{' + key + '}';
            while (result.indexOf(placeholder) !== -1) {
                result = result.replace(placeholder, vars[key] || '');
            }
        }
    }
    return result;
}

