function loadHookFn(path, hookName) {
    if (!path) return null;
    var fn = loadConfigFile(path);
    if (typeof fn !== 'function') {
        console.warn('configLoader: ' + hookName + ' "' + path + '" did not export a function — ignoring');
        return null;
    }
    return fn;
}

/**
