function buildConfigCandidates(params, customParams) {
    var candidates = [];
    // 1. Top-level configPath (e.g. jobParams.configPath or smAgent's p.configPath)
    if (params && params.configPath) {
        candidates.push({ path: params.configPath, logSuffix: '' });
